CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile read" ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY "Own profile update" ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_customer_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(new.id,coalesce(new.raw_user_meta_data->>'display_name',new.raw_user_meta_data->>'full_name','')); RETURN new; END $$;
CREATE TRIGGER jood_customer_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_customer_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,coalesce(raw_user_meta_data->>'display_name','') FROM auth.users ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.assign_first_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'user') ON CONFLICT DO NOTHING; RETURN new; END $$;
ALTER TABLE public.orders ADD COLUMN user_id uuid;
CREATE POLICY "Customers read own orders" ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.admin_sessions (session_id uuid PRIMARY KEY, user_id uuid NOT NULL, expires_at timestamptz NOT NULL);
GRANT ALL ON public.admin_sessions TO service_role;
ALTER TABLE public.admin_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.admin_login_attempts (key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, locked_until timestamptz, last_attempt timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.admin_login_attempts TO service_role;
ALTER TABLE public.admin_login_attempts ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.reserve_admin_attempt(_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.admin_login_attempts; BEGIN INSERT INTO public.admin_login_attempts(key) VALUES(_key) ON CONFLICT DO NOTHING; SELECT * INTO r FROM public.admin_login_attempts WHERE key=_key FOR UPDATE; IF r.locked_until>now() THEN RETURN false; END IF; IF r.last_attempt < now()-interval '15 minutes' THEN r.attempts:=0; END IF; UPDATE public.admin_login_attempts SET attempts=r.attempts+1,last_attempt=now(),locked_until=CASE WHEN r.attempts+1>=5 THEN now()+interval '15 minutes' ELSE NULL END WHERE key=_key; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.reserve_admin_attempt(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reserve_admin_attempt(text) TO service_role;
CREATE FUNCTION public.has_admin_access() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') AND EXISTS(SELECT 1 FROM public.admin_sessions s WHERE s.user_id=auth.uid() AND s.session_id::text=auth.jwt()->>'session_id' AND s.expires_at>now()) $$;
REVOKE ALL ON FUNCTION public.has_admin_access() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_admin_access() TO authenticated;
DO $$ DECLARE p record; q text; w text; role_list text; BEGIN FOR p IN SELECT * FROM pg_policies WHERE schemaname IN ('public','storage') AND (coalesce(qual,'') LIKE '%has_role%' OR coalesce(with_check,'') LIKE '%has_role%') AND tablename<>'user_roles' LOOP q:=regexp_replace(p.qual,'has_role\(auth.uid\(\), ''admin''::app_role\)','has_admin_access()','g'); w:=regexp_replace(p.with_check,'has_role\(auth.uid\(\), ''admin''::app_role\)','has_admin_access()','g'); SELECT string_agg(quote_ident(x),',') INTO role_list FROM unnest(p.roles) x; EXECUTE format('DROP POLICY %I ON %I.%I',p.policyname,p.schemaname,p.tablename); EXECUTE format('CREATE POLICY %I ON %I.%I AS %s FOR %s TO %s %s %s',p.policyname,p.schemaname,p.tablename,p.permissive,p.cmd,role_list,CASE WHEN q IS NULL THEN '' ELSE 'USING ('||q||')' END,CASE WHEN w IS NULL THEN '' ELSE 'WITH CHECK ('||w||')' END); END LOOP; END $$;
CREATE POLICY "Admin profiles read" ON public.profiles FOR SELECT TO authenticated USING(public.has_admin_access());
CREATE TABLE public.products (id text PRIMARY KEY, name text NOT NULL, category text NOT NULL, price_yer numeric NOT NULL, compare_at_yer numeric, data jsonb NOT NULL DEFAULT '{}', featured boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated;
GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published products" ON public.products FOR SELECT TO anon,authenticated USING(active);
CREATE POLICY "Admin products" ON public.products FOR ALL TO authenticated USING(public.has_admin_access()) WITH CHECK(public.has_admin_access());
